using System;using UnityEngine;
[Serializable]public sealed class TrainingSpatialHurt {public int partId;public Vector3 center,size;}
[Serializable]public sealed class TrainingSpatialKey {public float frame,rootForward;public Vector3 visualOffset,hitCenter,hitHalfSize;public TrainingSpatialHurt[] hurt=new TrainingSpatialHurt[0];public TrainingSpatialKey Copy()=>JsonUtility.FromJson<TrainingSpatialKey>(JsonUtility.ToJson(this));}
[CreateAssetMenu(menuName="Shioka/Move spatial profile")]
public sealed class TrainingMoveSpatialProfile:ScriptableObject {
 public TrainingSpatialKey[] keys=new TrainingSpatialKey[0];
 public bool Validate(out string error){error="";if(keys==null||keys.Length==0){error="Need keys";return false;}float previous=-1;foreach(var k in keys){if(k==null||!Finite(k.frame)||k.frame<0||k.frame<=previous||!Finite(k.rootForward)||!V(k.visualOffset)||!V(k.hitCenter)||!V(k.hitHalfSize)||k.hitHalfSize.x<=0||k.hitHalfSize.y<=0||k.hitHalfSize.z<=0){error="Finite sorted frames and positive box sizes required";return false;}var ids=new System.Collections.Generic.HashSet<int>();foreach(var h in k.hurt)if(h==null||!ids.Add(h.partId)||!V(h.center)||!V(h.size)||h.size.x<=0||h.size.y<=0||h.size.z<=0){error="Unique hurt IDs and positive sizes required";return false;}previous=k.frame;}if(keys[0].frame!=0||Mathf.Abs(keys[0].rootForward)>.00001f){error="Frame 0 root displacement must be zero";return false;}return true;}
 static bool Finite(float x)=>!float.IsNaN(x)&&!float.IsInfinity(x);static bool V(Vector3 x)=>Finite(x.x)&&Finite(x.y)&&Finite(x.z);
 public TrainingSpatialKey Sample(float frame){if(!Validate(out _))return null;var a=keys[0];var b=a;foreach(var k in keys){if(k.frame<=frame)a=k;if(k.frame>=frame){b=k;break;}b=k;}float t=b.frame>a.frame?Mathf.Clamp01((frame-a.frame)/(b.frame-a.frame)):0;var s=a.Copy();s.frame=frame;s.rootForward=Mathf.Lerp(a.rootForward,b.rootForward,t);s.visualOffset=Vector3.Lerp(a.visualOffset,b.visualOffset,t);s.hitCenter=Vector3.Lerp(a.hitCenter,b.hitCenter,t);s.hitHalfSize=Vector3.Lerp(a.hitHalfSize,b.hitHalfSize,t);foreach(var h in s.hurt){var next=Array.Find(b.hurt,x=>x.partId==h.partId);if(next!=null){h.center=Vector3.Lerp(h.center,next.center,t);h.size=Vector3.Lerp(h.size,next.size,t);}}return s;}
}
